          '**¿Necesitas clonación de voz?** → Sí: XTTS v2 (mejor calidad, licencia CPML) o F5-TTS (arquitectura más nueva, más rápido, CC-BY-NC-4.0) o Coqui VITS (buena calidad, MPL 2.0). No: Piper (velocidad), StyleTTS 2 (calidad).',
