    leadAnswerBlock:
      '**Piper é o melhor motor TTS local para velocidade em CPU e dispositivos embarcados — funciona em tempo real em uma Raspberry Pi 5 e não requer GPU.** XTTS v2 é a melhor opção de clonagem de voz local em 2026 (6 segundos de áudio de referência → voz clonada em 17 idiomas), mas requer entre 4 e 6 GB de VRAM em GPU e uma licença comercial para uso em produção. F5-TTS é uma alternativa de flow-matching mais moderna para clonagem de voz zero-shot — qualidade competitiva com inferência mais rápida do que XTTS v2 e uma comunidade de desenvolvimento ativa. Para equilibrar clonagem de voz com licença permissiva, Coqui TTS sobre o backend XTTS ou VITS é a escolha prática. Bark é o único motor de áudio generativo que produz risadas, suspiros e sons ambientes — capacidade única para projetos criativos, mas lento e menos controlável. StyleTTS 2 produz a narração em inglês mais natural, mas é apenas em inglês e não tem clonagem de voz.',
