          '**متطلبات VRAM:** Piper: معالج مركزي فقط. Kokoro: CPU / 1–2 جيجابايت. StyleTTS 2: 2–4 جيجابايت. Coqui VITS: 2–4 جيجابايت. F5-TTS: 3–5 جيجابايت. XTTS v2: 4–6 جيجابايت. Bark: 4–8 جيجابايت.',
