          '**المنازل الذكية:** برنامج Piper هو طبقة TTS الرئيسية لواجهات الصوت المحلية الدائمة — وقت فعلي على Raspberry Pi دون GPU. للاطلاع على مساعد صوتي محلي متكامل مع Home Assistant، راجع [مساعد الصوت المحلي للمنزل الذكي ←](/ar/smart-home/local-voice-assistant-smart-home).',
